const dataUriCache = new Map<string, string>();

export function getAppSvgString(appId: string): string | null {
  return ICON_SVGS[appId] ?? null;
}

export function getAppSvgDataUri(appId: string): string | null {
  const cached = dataUriCache.get(appId);
  if (cached) return cached;
  const svg = ICON_SVGS[appId];
  if (!svg) return null;
  const uri = `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
  dataUriCache.set(appId, uri);
  return uri;
}
